/*
 * Synopsis: TVLogger *
 *           CreateTVLogger(Widget, usptr_t *)
 *	
 *
 * Description: Creation of a "TVLogger" structure which is the 
 *    entry point for generating the log files. A shared memory arena
 *    must be passed in and is used to create semaphores which are used 
 *    during the logging process.
 *
 * Externals: NONE
 *
 * Returns: A Pointer to a TVLogger structure on success
 *          NULL - on failure
 *
 * Author:
 *		Stephen Lau
 * 
 * Date: June 1995
 *
 */
TVLogger *
CreateTVLogger(Widget parent)
{
  static char * funcName = "CreateTVLogger()";

  glmContext glmCtx = glmXFindContext (XtDisplay (parent),
				       XtScreen (parent),
				       True, 0);

  TSMTRINC ((LOG_MASK|1, 1));
  TSMTRACE ((LOG_MASK|1, funcName, "Entering."));

  tvLogger = (TVLogger *) malloc(sizeof(TVLogger));
  if (! tvLogger) {
    tsmError (funcName, "Creating logging structure.");
    TSMTRINC ((LOG_MASK|1, -1));
    return NULL;
  }

  /* INITIALIZE LOGGER */
  tvLogger->graphScale = 10.0;
  tvLogger->offsetScale = 0.0;
  tvLogger->freeze = FALSE;
  tvLogger->thread = 0;

  if (! tvuGetInt( TVU_CAVE ) ) {
    /* CREATE THE WIDGETS FOR THE GRAPHS */
    if(! TVLoggerCreateWidgets (tvLogger, parent, glmCtx)) {
      tsmError (funcName, "Unable to initialize logging graphs");
      TSMTRINC ((LOG_MASK|1, -1));
      return NULL;
    }
  }

  TSMTRACE ((LOG_MASK|1, funcName, "Done."));
  TSMTRINC ((LOG_MASK|1, -1));
  return tvLogger;
}

