/*
 * Synopsis: void TVLoggerShowGraphs(TVLogger *)
 *	
 *
 * Description: Pop up the graph log widget, start the rendering
 *
 * Externals: NONE
 *
 *
 * Returns: NONE
 *
 * Author:
 *		Stephen Lau
 * 
 * Date: June 1995
 *
 */

void
TVLoggerShowGraphs( TVLogger *tvLogger )
{
  static char *funcName = "TVLoggerShowGraphs()";

  TSMTRACE ((LOG_MASK|1, funcName, "Entering"));

  if( tvLogger == NULL ) {
    tsmError( funcName, "Hey idiot, try initializing the logger first" );
    return;
  }

  XtManageChild(tvLogger->mainForm);

  if ( tvLogger->thread == NULL ) {
    if ( pthr_create( &tvLogger->thread, "TS Logger",
		       (void (*)(void*))TVLoggerThread, tvLogger) )
      tsmError (funcName, "Unable to spawn TS Logger");
  }

  TSMTRACE ((LOG_MASK|1, funcName, "Done"));
}


