/*
 * Synopsis: static void TVLoggerX11Callback(Widget, XtPointer, XtPointer)
 *	
 *
 * Description: General all-purpose callback function. Right now it 
 *   serves to dismiss the drawing widget.
 *
 * Externals: NONE
 *
 *
 * Returns: NONE
 *
 * Author:
 *		Stephen Lau
 * 
 * Date: June 1995
 *		
 *
 */
static void
TVLoggerX11Callback(Widget    w, 
		    XtPointer client_data,
		    XtPointer call_data)
{
/*  static char *funcName = "TVLoggerX11Callback()";*/
  TVLogger *tvLogger = (TVLogger *) client_data;

  if( w != tvLogger->freezeWidget ) {
    glmRemoveRedraw (tvLogger->drawglmw);
    XtUnmanageChild(tvLogger->mainForm);
  } else {
    if( ! tvLogger->freeze ) {
      TerraVisionStopLogging();
      tvLogger->freeze = TRUE;
      tvLogger->freezeTime = PR_IntervalNow();
    } else {
      TerraVisionStartLogging();
      tvLogger->freeze = FALSE;
    }
  }
}

/*
 * Synopsis: static void TVLoggerWidgetInitCallback(Widget,
 *                                                  XtPointer, XtPointer)
 *
 * Description: Intializes the GL window for the graphs
 *
 *
 * Externals: DISPLAY to redirect the GL draws if we want to.
 *
 *
 * Returns: NONE
 *
 * Author:
 *		Stephen Lau
 * 
 * Date:
 *	June 1995
 *
 */
static void
TVLoggerWidgetInitCallback(Widget w, 
			   XtPointer client_data,
			   XtPointer call_data)
{ 
  static char * funcName = "TVLoggerInitCallback()";

  glmWindow glmw = (glmWindow) client_data;
  GLwDrawingAreaCallbackStruct * data = 
    (GLwDrawingAreaCallbackStruct *) call_data;

  TSMTRACE ((LOG_MASK|1, funcName, "widget %p \"%s\" glwm %p %dx%d",
	     w, XtName (w), glmw, data->width, data->height));

  glmMakeCurrentWindow (funcName, glmw); {
    TSMTRACE ((LOG_MASK|1, funcName, "viewport %s 0,0 %dx%d",
	       XtName (w), data->width+1, data->height+1));
    glViewport(0, 0, (GLuint) data->width+1, (GLuint) data->height+1);
  }; glmReleaseWindow (funcName, glmw);
}

