/*
 * Synopsis: void * TVLoggerThread(void *)
 *
 * Description: Signals to the widget that a redraw is required.
 *
 * Returns: void.
 *
 * Author: Lee Iverson
 *
 * Date: April 1997
 *
 */
static void *
TVLoggerThread (void *arg)
{
  static const char funcName[] = "TVLoggerThread()";
  TVLogger *tvLogger = (TVLogger *) arg; 
  long msec = 1000;

  TSMTRACE ((LOG_MASK|1, funcName, "Entering"));
  while (TVLoggerIsManaged (tvLogger)) {
    TVLoggerPostRedraw (tvLogger);

    /* This pauses for msec milliseconds. */
    tsmPause_ms (msec);
  }

  tvLogger->thread = 0;
  TSMTRACE ((LOG_MASK|1, funcName, "Done."));

  return 0;
}

/*
 * Synopsis: Boolean TVLoggerPostRedraw(TVLogger *)
 *
 * Description: Signals to the widget that a redraw is required.
 *              Locked is True when called from a context in which the widget
 *              is already locked.
 *
 * Returns: void.
 *
 * Author: Lee Iverson
 *
 * Date: February 1997
 *
 */
static void
TVLoggerPostRedraw (TVLogger * tvLogger)
{
  static char const *funcName = "TVLoggerPostRedraw";

  TSMTRACE ((LOG_MASK|1, funcName, ""));
  glmPostRedraw (tvLogger->drawglmw);
}

/*
 * Synopsis: Boolean TVLoggerIsManaged(TVLogger const * tvLogger)
 *
 * Description: Determines whether or not widget is managed.
 *
 * Returns: TRUE iff widget is managed.
 *
 * Author: Lee Iverson
 *
 * Date: May 1997
 *
 */
Boolean
TVLoggerIsManaged (TVLogger const * tvLogger)
{
  return XtIsManaged (tvLogger->drawWidget);
}

/*
 * Synopsis: void TVLoggerDraw();
 *	
 *
 * Description: Redraws the logger data as a XtWorkProc.
 *
 * Externals: The Display
 *
 *
 * Returns: FALSE
 *
 * Author:
 *		Stephen Lau
 * 
 * Date: June 1995
 *
 */
static void
TVLoggerDraw (glmWindow glmw, void * threadData)
{
  static char * funcName = "TVLoggerDraw()";
  PRIntervalTime currTime;
  TVLogger *tvLogger = (TVLogger *) threadData; 
  double currSeconds;
  int i;
  TsLog *tsLog = GetTsLog();

    TSMTRACE ((LOG_MASK|1, funcName, "Entering"));

    /* CALCULATE ELAPSED TIME */
    if(!tvLogger->freeze)
    {
      currTime = PR_IntervalNow();
      currSeconds = DoubleSeconds(currTime);
      tvLogger->lastTime = currSeconds;
    }
    else
    {
      currSeconds = DoubleSeconds(tvLogger->freezeTime);
    }

    PR_Lock(tsLog->logLock);

    /* DRAW THE LEGENDS */
    for(i = 0; i < TV_NUM_GRAPHS; i++)
    {
      glmMakeCurrentWindow (funcName, tvLogger->legendglmw[i]); {
	glDisable (GL_DITHER);
	glClearColor (logColors[i][0]/255.0,
		      logColors[i][1]/255.0,
		      logColors[i][2]/255.0,
		      logColors[i][3]/255.0);
	glClear(GL_COLOR_BUFFER_BIT);
      }; glmReleaseWindow (funcName, tvLogger->legendglmw[i]);
    }
    for (i = 0 ; i < 3; i++)
    {
      glmMakeCurrentWindow (funcName, tvLogger->legendglmw[i+TV_NUM_GRAPHS]); {
	glDisable (GL_DITHER);
	glClearColor (reqColors[i][0]/255.0,
		      reqColors[i][1]/255.0,
		      reqColors[i][2]/255.0,
		      reqColors[i][3]/255.0);
	glClear(GL_COLOR_BUFFER_BIT);
      }; glmReleaseWindow (funcName, tvLogger->legendglmw[i+TV_NUM_GRAPHS]);
    }

    /* DRAW THE DATA */
    TsLoggerDrawLogFiles(tvLogger, currSeconds);
    TsLoggerDrawRequests(tvLogger, currSeconds);
    TsLoggerDrawTextureCache(tvLogger, currSeconds);
    TsLoggerDrawCache(tvLogger, currSeconds);

    PR_Unlock(tsLog->logLock);

    TSMTRACE ((LOG_MASK|1, funcName, "Done."));
}

/*
 * Synopsis: void TvLoggerSliderChangedCB(Widget,
 *					  XtPointer,
 *					  Xtpointer)
 *
 * Description: When the user clicks and drags the sacle widget, this callback
 *      is called and the value is retrieved from the widget. The value is
 *      copied to the tvLogger * for later use.
 *
 * Externals:
 *
 *
 * Returns: NULL
 *
 * Author:
 *		Stephen Lau
 *
 * Date: July 1995
 *
 */
static void
TVLoggerSliderChangedCB(Widget    w,
			   XtPointer client_data,
			   XtPointer call_data)
{
/* static char const * funcName = "TVLoggerSlideChangedCB()";*/
 TVLogger * tvLogger = (TVLogger *) client_data;
 int val;

    /* GET THE VALUE FROM THE WIDGET AND SAVE IT FOR LATER USE */
    XmScaleGetValue(w, &val);
    if(w == tvLogger->scaleWidget)
    {
	tvLogger->graphScale = (float) val;
    }
    if(w == tvLogger->offsetWidget)
    {
	tvLogger->offsetScale = (float) val;
    }
}

/*
 * Synopsis: void TVLoggerUpdateWidgets()
 *
 * Description: Update the displayed rates
 *
 * Returns: void
 *
 * Author: Stephen Lau
 * 
 * Date: July 1998 
 *
 */

void
TVLoggerUpdateWidgets( TVLogger *tvLogger )
{
/*  static char const *funcName = "TVLoggerUpdateWidgets()";*/
  char buffer[30];
  int i;
  TsLog *tsLog = GetTsLog();
  XmString string;

  for ( i = 0; i < TV_NUM_GRAPHS; i++ ) {
    if ( tsLog->averages[i] == -1 )
      sprintf( buffer, "N/A" );
    else
      sprintf( buffer, "Average = %4.2fms", tsLog->averages[i] * 1000.0 );
    
    string = tvXmString( buffer );
    XtVaSetValues( tvLogger->averageWidgets[i], XmNlabelString, string, NULL );
    XmStringFree( string );
  }
}

/*
 * Synopsis: void TsLoggerDrawRequests()
 *
 * Description: Draw the request list polygons
 *
 * Externals: Display
 *
 * Returns: void
 *
 * Author: Stephen Lau
 * 
 * Date: June 1995
 *
 */

static void
TsLoggerDrawRequests( TVLogger * tvLogger, double currSeconds )
{
  static char const * funcName = "TsLoggerDrawRequests()";
  int i, j;
  int max = 0;
  float v[2];
  float val;
  TsLog *tsLog = GetTsLog();
  int currLog = tsLog->currLog[TV_REQUEST_LOG];

  glmMakeCurrentWindow (funcName, tvLogger->requestglmw); {
    for (i = 0; i < MAX_HISTORY_LOG; i++) {
      for (j = 0; j < 3; j++) {
	if (tsLog->requestHistory[i][j] > max) {
	  max = tsLog->requestHistory[i][j];
	}
      }
    }
    val = 10 * (trunc((float) max / 10.0) + 1);

    glDisable (GL_DITHER);
    glClearColor (0xB2/255.0, 0xB2/255.0, 0xB2/255.0, 0x00/255.0);
    glClear(GL_COLOR_BUFFER_BIT);

#if 0
    glMatrixMode(GL_PROJECTION);
    glLoadIdentity();
    gluOrtho2D(tvLogger->graphScale,  0,  0,  val);
    glColor4ub (0x57, 0x57, 0x57, 0xFF);
    glBegin(GL_LINES); {
      for(i = 0; i <= tvLogger->graphScale; i++) {
	v[0] = i;
	v[1] = 0;
	glVertex2fv(v);
	v[1] = val;
	glVertex2fv(v);
      }
      
      for(i = 0; i <= val; i += 10) {
	v[0] = 0;
	v[1] = i;
	glVertex2fv(v);
	v[0] = tvLogger->graphScale;
	glVertex2fv(v);
	}
    }; glEnd();
#endif
    
    /* Render the request list polygons on the graph */

    glMatrixMode(GL_PROJECTION);
    glLoadIdentity();
    gluOrtho2D(tvLogger->graphScale + tvLogger->offsetScale,
	       tvLogger->offsetScale, 0,  val);

    glLineWidth((GLfloat)(2));
    for( j = 0; j < 3; j++ ) {

      glColor4ubv( reqColors[j] );

      glBegin(GL_LINE_STRIP); {

	for ( i = currLog; i < MAX_HISTORY_LOG; i++ ) {
	  v[0] = currSeconds -
	    DoubleSeconds(tsLog->logHistory[TV_REQUEST_LOG][i][1]);
	  
	  if ( i != currLog )
	    v[1] = tsLog->requestHistory[i - 1][j];
	  else
	    v[1] = tsLog->requestHistory[i][j];
	  glVertex2fv( v );
	}
	
	for( i = 0; i < currLog; i++ ) {
	  v[0] = currSeconds -
	      DoubleSeconds(tsLog->logHistory[TV_REQUEST_LOG][i][1]);
	  if( i != 0 )
	    v[1] = tsLog->requestHistory[i - 1][j];
	  else
	    v[1] = tsLog->requestHistory[MAX_HISTORY_LOG - 1][j];
	  glVertex2fv( v );
	  
	  v[1] = tsLog->requestHistory[i][j];
	  glVertex2fv( v );
	}
	}; glEnd();
    }
    
    /* Render the scale axes lines on the graph */
    
    glMatrixMode(GL_PROJECTION);
    glLoadIdentity();
    gluOrtho2D(tvLogger->graphScale,  0,  0,  val);
    glColor4ub (0x57, 0x57, 0x57, 0xFF);
    
    glLineWidth((GLfloat)(1));
    glBegin(GL_LINES); {
      for(i = 0; i <= tvLogger->graphScale; i++) {
	v[0] = i;
	v[1] = 0;
	glVertex2fv(v);
	v[1] = val;
	glVertex2fv(v);
      }
      for(i = 0; i <= val; i += 10) {
	v[0] = 0;
	v[1] = i;
	glVertex2fv(v);
	v[0] = tvLogger->graphScale;
	glVertex2fv(v);
      }
    }; glEnd();
    
  }; glmReleaseWindow (funcName, tvLogger->requestglmw);
}

/*
 * Synopsis: void TsLoggerDrawTextureCache()
 *
 *
 * Description: Draws the texture cache utilization
 *
 *
 * Externals: The DISPLAY
 *
 *
 * Returns: NOTHING
 *
 * Author:
 *		Stephen Lau
 * 
 * Date: June 1995
 *
 */
static void
TsLoggerDrawTextureCache(TVLogger * tvLogger,
			 double currSeconds)
{ 
 static char const * funcName = "TsLoggerDrawTextureCache()";
 int i, j;
 int max = 0;
 float v[2];
 float val;
 TsLog *tsLog = GetTsLog();
 int currLog = tsLog->currNumTexture;

 glmMakeCurrentWindow (funcName, tvLogger->textureglmw); {

   for (i = 0; i < MAX_HISTORY_LOG; i++) {
     for (j = 0; j < 2; j++) {
       if (tsLog->numTextureLog[i][j].val > max) {
	 max = tsLog->numTextureLog[i][j].val;
       }
     }
   }
   val = 10 * (trunc((float) max / 10.0) + 1);

   if (val > 200) {
     tsmError(funcName, "Whoops textures %d > 200", val);
   }

   glMatrixMode (GL_PROJECTION);
   glLoadIdentity ();
   gluOrtho2D (tvLogger->graphScale, 0, 0, val);
   glDisable (GL_DITHER);
   glClearColor (0xB2/255.0, 0xB2/255.0, 0xB2/255.0, 0x00/255.0);
   glClear (GL_COLOR_BUFFER_BIT);
   glColor4ub (0x57, 0x57, 0x57, 0xFF);
   glBegin (GL_LINES); {
     for (i = 0; i <= tvLogger->graphScale; i++) {
       v[0] = i;
       v[1] = 0;
       glVertex2fv(v);
       v[1] = val;
       glVertex2fv(v);
     }
     for (i = 0; i <= val; i += 10) {
       if (i >= 100) {
	 glColor4ub (0xFF, 0x00, 0x00, 0xFF);
       } else {
	 glColor4ub (0xFF, 0x57, 0x57, 0x57);
       }
       v[0] = 0;
       v[1] = i;
       glVertex2fv (v);
       v[0] = tvLogger->graphScale;
       glVertex2fv (v);
     }
   }; glEnd();

   glMatrixMode (GL_PROJECTION);
   glLoadIdentity ();
   gluOrtho2D (tvLogger->graphScale + tvLogger->offsetScale,
	       tvLogger->offsetScale, 0,  val);
   
   glLineWidth ((GLfloat)(2));
   for (j = 0; j < 2; j++) {
     glColor4ubv (texColors[j]);
     glBegin (GL_LINE_STRIP); {
       for (i = currLog; i < MAX_HISTORY_LOG; i++) {
	 v[0] = currSeconds -
	   DoubleSeconds (tsLog->numTextureLog[i][j].logTime);
	 if (i != currLog) {
	   v[1] = tsLog->numTextureLog[i -1][j].val;
	   glVertex2fv (v);
	 }
	 v[1] = tsLog->numTextureLog[i][j].val;
	 glVertex2fv (v);
       }
       for (i = 0; i < currLog; i++) {
	 v[0] = currSeconds -
	   DoubleSeconds (tsLog->numTextureLog[i][j].logTime);
	 if (i != 0) {
	   v[1] = tsLog->numTextureLog[i - 1][j].val;
	 } else {
	   v[1] = tsLog->numTextureLog[MAX_HISTORY_LOG - 1][j].val;
	 }
	 glVertex2fv (v);
	 v[1] = tsLog->numTextureLog[i][j].val;
	 glVertex2fv (v);
       }
     }; glEnd ();
   }
 }; glmReleaseWindow (funcName, tvLogger->textureglmw);
}

/*
 * Synopsis: void TsLoggerDrawCache()
 *
 * Description:  Draws when we read in a tile
 *
 * Externals: DISPLAY
 *
 * Returns: NOTHING
 *
 * Author: Stephen Lau
 * 
 * Date: 1995
 *
 */

static void
TsLoggerDrawCache( TVLogger * tvLogger, double currSeconds )
{
  static char const * funcName = "TsLoggerDrawCache()";
  int i;
  float v[2];
  int max = 0;
  TsLog *tsLog = GetTsLog();

  for ( i = 0; i < MAX_HISTORY_LOG; i++ )
    if ( tsLog->serverLogs[i].val > max ) 
      max = tsLog->serverLogs[i].val;

  glmMakeCurrentWindow (funcName, tvLogger->cacheglmw); {
  
    glMatrixMode (GL_PROJECTION);
    glLoadIdentity ();
    gluOrtho2D (tvLogger->graphScale, 0,  0, max + 2);
    glDisable (GL_DITHER);
    glClearColor (0xB2/255.0, 0xB2/255.0, 0xB2/255.0, 0x00/255.0);
    glClear (GL_COLOR_BUFFER_BIT);
    glColor4ub (0xFF, 0x57, 0x57, 0x57);
    
    glBegin (GL_LINES); {
      for (i = 0; i <= tvLogger->graphScale; i++) {
	v[0] = i;
	v[1] = 0;
	glVertex2fv (v);
	v[1] = max + 2;
	glVertex2fv (v);
      }
      for (i = 0; i < max + 2; i++) {
	v[0] = 0;
	v[1] = i;;
	glVertex2fv (v);
	v[0] = tvLogger->graphScale;
	glVertex2fv (v);
      }
    }; glEnd ();
    
    glMatrixMode (GL_PROJECTION);
    glLoadIdentity ();
    gluOrtho2D (tvLogger->graphScale + tvLogger->offsetScale,
		tvLogger->offsetScale, 0,  max + 2);
    
    glLineWidth ((GLfloat)(3));
    glBegin (GL_LINES); {
      for (i = 0; i < MAX_HISTORY_LOG; i++) {
	glColor4ubv (logColors[tsLog->serverLogs[i].val]);
	v[1] = tsLog->serverLogs[i].val + 1 - .25;
	v[0] = currSeconds -
	  DoubleSeconds (tsLog->serverLogs[i].logTime);
	glVertex2fv (v);
	v[1] = tsLog->serverLogs[i].val + 1 + .25;
	glVertex2fv (v);
      }
    }; glEnd ();
  }; glmReleaseWindow (funcName, tvLogger->cacheglmw);
}

/*
 * Synopsis: void TsLoggerDrawLogFiles()
 *
 * Description: Draws the log history
 *
 * Externals: The DISPLAY
 *
 * Returns: void
 *
 * Author: Stephen Lau
 * 
 * Date: June 1995
 *
 */

static void
TsLoggerDrawLogFiles( TVLogger *tvLogger, double currSeconds )
{
  static char const * funcName = "TsLoggerDrawLogFiles()";
  int   i, j;
  float v[2];
  TsLog *tsLog = GetTsLog();

  glmMakeCurrentWindow (funcName, tvLogger->drawglmw); {

    glMatrixMode(GL_PROJECTION);
    glLoadIdentity();
    gluOrtho2D(tvLogger->graphScale, 0, 0, TV_NUM_GRAPHS + 1);
    glDisable (GL_DITHER);
    glClearColor (0xB2/255.0, 0xB2/255.0, 0xB2/255.0, 0x00/255.0);
    glClear(GL_COLOR_BUFFER_BIT);

    glColor4ub (0x57, 0x57, 0x57, 0xFF);
    glBegin(GL_LINES); {
      for(i = 0; i <= tvLogger->graphScale; i++) {
	v[0] = i;
	v[1] = 0;
	glVertex2fv(v);
	v[1] = TV_NUM_GRAPHS + 1;
	glVertex2fv(v);
      }
      for(i = 0; i <= TV_NUM_GRAPHS + 1; i++) {
	v[0] = 0;
	v[1] = i;
	glVertex2fv(v);
	v[0] = tvLogger->graphScale;
	glVertex2fv(v);
      }
    }; glEnd();

    glMatrixMode(GL_PROJECTION);
    glLoadIdentity();
    gluOrtho2D(tvLogger->graphScale + tvLogger->offsetScale,
	       tvLogger->offsetScale, 0, TV_NUM_GRAPHS + 1);
    
    glColor4ub (0x00, 0xFF, 0x00, 0x00);

    glLineWidth((GLfloat)(3));
    glBegin(GL_LINES); {
      for(i = 0; i < TV_NUM_GRAPHS; i++) {
	glColor4ubv (logColors[i]);
	v[1] = i + 1;
	for(j = 0; j < MAX_HISTORY_LOG; j++) {
	  v[0] = currSeconds -
	    DoubleSeconds(tsLog->logHistory[i][j][0]);
	  glVertex2fv(v);
	  v[0] = currSeconds - 
	    DoubleSeconds(tsLog->logHistory[i][j][1]);
	  glVertex2fv(v);
	  
	  v[0] = currSeconds -
	    DoubleSeconds(tsLog->logHistory[i][j][0]);
	  v[1] -= .25;
	  glVertex2fv(v);
	  v[1] += .5;
	  glVertex2fv(v);
	  
	  v[0] = currSeconds -
	    DoubleSeconds(tsLog->logHistory[i][j][1]);
	  glVertex2fv(v);
	  v[1] -= .5;
	  glVertex2fv(v);
	  
	  v[1] += .25;
	}
      }
    }; glEnd ();
  }; glmReleaseWindow (funcName, tvLogger->drawglmw);
}
